{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"md"},"children":["composer","run-note"]}}
{"op":"add","path":"/elements/composer","value":{"type":"Composer","props":{"headline":"Find the look for your next deck","lede":"Tell us about the talk, and we'll sketch the looks it could wear.","runLabel":"Draw my directions","columns":"2"},"on":{"press":[{"action":"validateForm"},{"action":"run"}]},"children":["group-talk","group-look"]}}
{"op":"add","path":"/elements/group-talk","value":{"type":"FieldGroup","props":{"title":"The talk"},"children":["topic-input","goal-segmented","audience-segmented"]}}
{"op":"add","path":"/elements/topic-input","value":{"type":"Input","props":{"label":"Topic","name":"topic","placeholder":"e.g. Our Series A story","value":{"$bindState":"/inputs/brief/topic"},"checks":[{"type":"required","message":"Tell us what the talk is about."}]},"children":[]}}
{"op":"add","path":"/elements/goal-segmented","value":{"type":"Segmented","props":{"label":"Goal","name":"goal","options":["pitch investors","sell to clients","internal training","keynote"],"value":{"$bindState":"/inputs/brief/goal"}},"children":[]}}
{"op":"add","path":"/elements/audience-segmented","value":{"type":"Segmented","props":{"label":"Audience","name":"audience","options":["executives","technical team","general public"],"value":{"$bindState":"/inputs/brief/audience"}},"children":[]}}
{"op":"add","path":"/elements/group-look","value":{"type":"FieldGroup","props":{"title":"The look"},"children":["tone-segmented","brand-input","references-input"]}}
{"op":"add","path":"/elements/tone-segmented","value":{"type":"Segmented","props":{"label":"Tone","name":"tone","options":["formal","playful","innovative","trustworthy","artsy"],"value":{"$bindState":"/inputs/brief/tone"}},"children":[]}}
{"op":"add","path":"/elements/brand-input","value":{"type":"Input","props":{"label":"Brand guidelines","name":"brand_guidelines","placeholder":"Colours, fonts, logo rules","value":{"$bindState":"/inputs/brief/brand_guidelines"}},"children":[]}}
{"op":"add","path":"/elements/references-input","value":{"type":"MthdsField","props":{"path":"/inputs/brief/existing_references","label":"References","hint":"Past decks or templates to follow or avoid."},"children":[]}}
{"op":"add","path":"/elements/run-note","value":{"type":"Stack","props":{"direction":"vertical","gap":"sm","align":"center"},"children":["run-note-text"]}}
{"op":"add","path":"/elements/run-note-text","value":{"type":"Text","props":{"text":"You'll get several directions, each a theme with its title slide drawn in it. Only the topic is needed to start.","variant":"muted"},"children":[]}}
